import { useEffect } from "react";

/**
 * Hook that listens for Escape and Ctrl+Enter keyboard shortcuts,
 * commonly used in dialogs for cancel and confirm actions.
 */
export function useDialogShortcuts(handleEsc: () => void, handleEnter: () => void): void {
    useEffect(() => {
        const controller = new AbortController();

        document.addEventListener(
            "keydown",
            (event: KeyboardEvent) => {
                if (event.key === "Escape") {
                    handleEsc();
                } else if (event.key === "Enter" && (event.ctrlKey || event.metaKey)) {
                    handleEnter();
                }
            },
            { signal: controller.signal }
        );

        return () => controller.abort();
    }, [handleEsc, handleEnter]);
}
